macro_rules! BatchSize {
    () => {
        # [doc = " Argument to [`Bencher::iter_batched`] and [`Bencher::iter_batched_ref`] which controls the"] # [doc = " batch size."] # [doc = ""] # [doc = " Generally speaking, almost all benchmarks should use `SmallInput`. If the input or the result"] # [doc = " of the benchmark routine is large enough that `SmallInput` causes out-of-memory errors,"] # [doc = " `LargeInput` can be used to reduce memory usage at the cost of increasing the measurement"] # [doc = " overhead. If the input or the result is extremely large (or if it holds some"] # [doc = " limited external resource like a file handle), `PerIteration` will set the number of iterations"] # [doc = " per batch to exactly one. `PerIteration` can increase the measurement overhead substantially"] # [doc = " and should be avoided wherever possible."] # [doc = ""] # [doc = " Each value lists an estimate of the measurement overhead. This is intended as a rough guide"] # [doc = " to assist in choosing an option, it should not be relied upon. In particular, it is not valid"] # [doc = " to subtract the listed overhead from the measurement and assume that the result represents the"] # [doc = " true runtime of a function. The actual measurement overhead for your specific benchmark depends"] # [doc = " on the details of the function you're benchmarking and the hardware and operating"] # [doc = " system running the benchmark."] # [doc = ""] # [doc = " With that said, if the runtime of your function is small relative to the measurement overhead"] # [doc = " it will be difficult to take accurate measurements. In this situation, the best option is to use"] # [doc = " [`Bencher::iter`] which has next-to-zero measurement overhead."] # [derive (Debug , Eq , PartialEq , Copy , Hash , Clone)] pub enum BatchSize { # [doc = " `SmallInput` indicates that the input to the benchmark routine (the value returned from"] # [doc = " the setup routine) is small enough that millions of values can be safely held in memory."] # [doc = " Always prefer `SmallInput` unless the benchmark is using too much memory."] # [doc = ""] # [doc = " In testing, the maximum measurement overhead from benchmarking with `SmallInput` is on the"] # [doc = " order of 500 picoseconds. This is presented as a rough guide; your results may vary."] SmallInput , # [doc = " `LargeInput` indicates that the input to the benchmark routine or the value returned from"] # [doc = " that routine is large. This will reduce the memory usage but increase the measurement"] # [doc = " overhead."] # [doc = ""] # [doc = " In testing, the maximum measurement overhead from benchmarking with `LargeInput` is on the"] # [doc = " order of 750 picoseconds. This is presented as a rough guide; your results may vary."] LargeInput , # [doc = " `PerIteration` indicates that the input to the benchmark routine or the value returned from"] # [doc = " that routine is extremely large or holds some limited resource, such that holding many values"] # [doc = " in memory at once is infeasible. This provides the worst measurement overhead, but the"] # [doc = " lowest memory usage."] # [doc = ""] # [doc = " In testing, the maximum measurement overhead from benchmarking with `PerIteration` is on the"] # [doc = " order of 350 nanoseconds or 350,000 picoseconds. This is presented as a rough guide; your"] # [doc = " results may vary."] PerIteration , # [doc = " `NumBatches` will attempt to divide the iterations up into a given number of batches."] # [doc = " A larger number of batches (and thus smaller batches) will reduce memory usage but increase"] # [doc = " measurement overhead. This allows the user to choose their own tradeoff between memory usage"] # [doc = " and measurement overhead, but care must be taken in tuning the number of batches. Most"] # [doc = " benchmarks should use `SmallInput` or `LargeInput` instead."] NumBatches (u64) , # [doc = " `NumIterations` fixes the batch size to a constant number, specified by the user. This"] # [doc = " allows the user to choose their own tradeoff between overhead and memory usage, but care must"] # [doc = " be taken in tuning the batch size. In general, the measurement overhead of `NumIterations`"] # [doc = " will be larger than that of `NumBatches`. Most benchmarks should use `SmallInput` or"] # [doc = " `LargeInput` instead."] NumIterations (u64) , # [doc (hidden)] __NonExhaustive , }
    };
}

BatchSize!();